{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE maplemonk.Pronk_db_Product_FACEBOOK_CONSOLIDATED_intermediate AS select Adset_Name ,Adset_ID ,FB.ad_id ,FB.ad_name ,fb.Account_Name ,Account_ID ,Campaign_Name ,Campaign_ID ,TRIM(SPLIT(fb.product_id, \',\')[SAFE_OFFSET(0)]) AS product_id_final ,TRIM(SPLIT(fb.product_id, \',\')[SAFE_OFFSET(1)]) AS product_name ,cast(Fb.date_start as date) Date ,SUM(CLICKS) Clicks ,sum(ifnull(inline_link_clicks,0)) Link_Clicks ,SUM(SPEND) Spend ,SUM(IMPRESSIONS) Impressions ,SUM(ifnull(Fc.Conversions,0)) Conversions ,sum(ifnull(reach,0)) reach ,sum(ifnull(frequency,0)) as frequency ,SUM(ifnull(Fcv.Conversion_Value,0)) Conversion_Value ,sum(ifnull(fd.add_to_carts,0)) Add_to_carts ,sum(ifnull(fdv.add_to_cart_value,0)) Add_to_cart_value ,sum(ifnull(fe.landing_page_views,0)) Landing_page_views ,sum(ifnull(ff.initiate_checkouts,0)) Initiate_checkouts ,sum(ifnull(ffv.initiate_checkouts_value,0)) Initiate_checkouts_value ,\'Facebook\' Channel ,\'Facebook_Custom_Facebook_Marketing_Pronk_db_Meta\' Account from( select * from maplemonk.Pronk_fb_ads_product_level_new_customcampaigns_data ) FB left join ( select ad_id ,product_id ,date_start ,SUM(CAST(JSON_EXTRACT_SCALAR(C, \'$.value\') AS FLOAT64)) AS conversions FROM maplemonk.Pronk_fb_ads_product_level_new_customcampaigns_data LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C, \'$.action_type\') = \'offsite_conversion.fb_pixel_purchase\' and TRIM(SPLIT(product_id, \',\')[SAFE_OFFSET(1)]) is not null group by 1,2,3 )Fc ON Fb.ad_id = Fc.ad_id and Fb.date_start=Fc.date_start and Fb.product_id = Fc.product_id left join ( select ad_id ,product_id ,date_start ,SUM(ifnull(CAST(JSON_EXTRACT_SCALAR(CV, \'$.value\') AS FLOAT64),0)) AS conversion_value FROM maplemonk.Pronk_fb_ads_product_level_new_customcampaigns_data LEFT JOIN UNNEST(ACTION_VALUES) CV WHERE JSON_EXTRACT_SCALAR(CV, \'$.action_type\') = \'offsite_conversion.fb_pixel_purchase\' and TRIM(SPLIT(product_id, \',\')[SAFE_OFFSET(1)]) is not null group by 1,2,3 )Fcv ON Fb.ad_id = Fcv.ad_id and Fb.date_start=Fcv.date_start and Fb.product_id = Fcv.product_id left join ( select ad_id ,date_start ,product_id ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) add_to_carts from maplemonk.Pronk_fb_ads_product_level_new_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_add_to_cart\' group by 1,2,3 having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Fd ON Fb.ad_id = Fd.ad_id and Fb.date_start=Fd.date_start and fb.product_id = fd.product_id left join ( select ad_id ,date_start ,product_id ,SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) Add_to_cart_Value from maplemonk.Pronk_fb_ads_product_level_new_customcampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_add_to_cart\' group by 1,2,3 having SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) is not null )Fdv ON Fb.ad_id = Fdv.ad_id and Fb.date_start=Fdv.date_start and fb.product_id = fdv.product_id left join ( select ad_id ,date_start ,product_id ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) Landing_page_views from maplemonk.Pronk_fb_ads_product_level_new_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'landing_page_view\' group by 1,2,3 having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Fe ON Fb.ad_id = Fe.ad_id and Fb.date_start=Fe.date_start and fb.product_id = fe.product_id left join ( select ad_id ,date_start ,product_id ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) Initiate_checkouts from maplemonk.Pronk_fb_ads_product_level_new_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_initiate_checkout\' group by 1,2,3 having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Ff ON Fb.ad_id = Ff.ad_id and Fb.date_start=Ff.date_start and fb.product_id=ff.product_id left join ( select ad_id ,date_start ,product_id ,SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) Initiate_checkouts_Value from maplemonk.Pronk_fb_ads_product_level_new_customcampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_initiate_checkout\' group by 1,2,3 having SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) is not null )Ffv ON Fb.ad_id = Ffv.ad_id and Fb.date_start=Ffv.date_start and fb.product_id=ffv.product_id GROUP BY Adset_Name, Adset_ID, fb.ad_id, fb.AD_NAME, Account_Name, Account_ID, Campaign_Name, Campaign_ID, Fb.date_start, TRIM(SPLIT(fb.product_id, \',\')[SAFE_OFFSET(0)]), TRIM(SPLIT(fb.product_id, \',\')[SAFE_OFFSET(1)]); CREATE OR REPLACE TABLE maplemonk.Pronk_db_Product_FACEBOOK_CONSOLIDATED as SELECT a.*, coalesce(p.sku, v.sku) AS SKU, coalesce(a.product_name, p.product_name_final, v.product_name_final) as product_name_final, coalesce(p.category, v.category) AS PRODUCT_CATEGORY from maplemonk.Pronk_db_Product_FACEBOOK_CONSOLIDATED_intermediate a left join ( SELECT product_id, LOWER(TRIM(sku_code)) AS SKU, PRODUCT_NAME_Final, category from `maplemonk.PRONK_SHOPIFY_FACT_ITEMS` QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(TRIM(product_id)) ORDER BY DATE(order_timestamp) DESC) = 1 ) p ON LOWER(REGEXP_REPLACE(a.product_id_final, r\'^-+|-+$\', \'\')) = LOWER(REGEXP_REPLACE(p.product_id, r\'^-+|-+$\', \'\')) left join ( SELECT variant_id, LOWER(TRIM(sku_code)) AS SKU, PRODUCT_NAME_Final, category FROM `maplemonk.PRONK_SHOPIFY_FACT_ITEMS` QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(TRIM(variant_id)) ORDER BY DATE(order_timestamp) DESC) = 1 ) v ON LOWER(REGEXP_REPLACE(a.product_id_final, r\'^-+|-+$\', \'\')) = LOWER(REGEXP_REPLACE(v.variant_id, r\'^-+|-+$\', \'\'))",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
